 13 // Identity tells one process from a later one that got the same PID
 14 // (DEVDESK-709). It is the creation stamp in the operating system's own unit,
 15 // read once per PID when the table is listed. It is opaque: the interface only
 16 // asks Verifiable, and this package compares. The zero value is "unknown", which
 17 // Kill refuses, so a caller that forgets the identity cannot send a signal.
 18 type Identity struct {
 19     kind identityKind
 20     raw  uint64
 21 }
 22 
 23 type identityKind uint8
 24 
 25 const (
 26     // identityNone is the zero value: not read, or unreadable.
 27     identityNone identityKind = iota
 28     // identityKnown carries the creation stamp, in the unit of the OS.
 29     identityKnown
 30     // identityDeferred is Windows only: the listing stopped reading because its
 31     // budget ran out. raw is the listing instant (Unix ns); the stamp is read
 32     // when the confirmation opens (ConfirmIdentity).
 33     identityDeferred
 34 )
 35 
 36 // The Windows budget and slack (S-01b criterion 7, hypothesis H1).
 37 const (
 38     // windowsIdentityBudget caps what reading identities adds to one refresh on
 39     // Windows. Past it the remaining PIDs are deferred. The starting value of the
 40     // story: adjust it from docs/measurements.
 41     windowsIdentityBudget = 100 * time.Millisecond
 42     // windowsBirthSlack is the granularity allowed between a creation time and the
 43     // listing instant before a process counts as born before the listing.
 44     windowsBirthSlack = 100 * time.Millisecond
 45 )
 46 
 47 // Verifiable reports whether a stop can still be attempted for the row: the
 48 // identity is known, or deferred and read when the confirmation opens.
 49 func (i Identity) Verifiable() bool { return i.kind != identityNone }
 50 
 51 // Conflicts reports whether two identities say, with certainty, that they are
 52 // two different processes: both known and different. An unknown or deferred one
 53 // never conflicts.
 54 func (i Identity) Conflicts(j Identity) bool {
 55     return i.kind == identityKnown && j.kind == identityKnown && i.raw != j.raw
 56 }
