 58 // deferredAt is the identity of a PID not read at the listing taken at listedAt.
 59 func deferredAt(listedAt time.Time) Identity {
 60     return Identity{kind: identityDeferred, raw: uint64(listedAt.UnixNano())} //nolint:gosec // listing instants are after 1970
 61 }
