 83 // UnverifiableError is the refusal when DevDesk cannot tell which process holds
 84 // the PID. It is DevDesk's own decision, not the system's: it wraps no OS
 85 // sentinel, so the interface cannot read it as "refused by the system".
 86 type UnverifiableError struct {
 87     PID   int
 88     Cause error // for the log only; deliberately not returned by Unwrap
 89 }
 90 
 91 func (e *UnverifiableError) Error() string {
 92     return fmt.Sprintf("Cannot verify which process PID %d is — not stopped", e.PID)
 93 }
