103 // parseStartTicks reads the starttime (field 22, ticks since boot) of a
104 // /proc/<pid>/stat line. The command name (field 2) sits between parentheses and
105 // may hold spaces and parentheses itself, so the fields are counted from the
106 // last ")".
107 func parseStartTicks(stat []byte) (uint64, error) {
108     end := bytes.LastIndexByte(stat, ')')
109     if end < 0 {
110         return 0, errors.New("no closing parenthesis in the stat line")
111     }
112     // Fields 3 onward follow the name: field 22 is the 20th of them.
113     const startIndex = 22 - 3
114     fields := bytes.Fields(stat[end+1:])
115     if len(fields) <= startIndex {
116         return 0, fmt.Errorf("the stat line stops at field %d, before starttime (22)", len(fields)+2)
117     }
118     ticks, err := strconv.ParseUint(string(fields[startIndex]), 10, 64)
119     if err != nil {
120         return 0, fmt.Errorf("reading starttime from the stat line: %w", err)
121     }
122     return ticks, nil
123 }
