125 // timevalStamp is a macOS process start (seconds and microseconds) as one value.
126 func timevalStamp(sec int64, usec int32) uint64 {
127     return uint64(sec)*1_000_000 + uint64(usec) //nolint:gosec // a start time is positive
128 }
129 
130 // unixAsFiletime is the Unix epoch as a Windows FILETIME (100 ns since 1601).
131 const unixAsFiletime = 116444736000000000
132 
133 // filetimeUnixNano turns a Windows FILETIME into Unix nanoseconds.
134 func filetimeUnixNano(raw uint64) int64 {
135     return (int64(raw) - unixAsFiletime) * 100 //nolint:gosec // FILETIMEs of this era fit in int64
136 }
