138 // birth says where a Windows creation time falls against the listing instant.
139 type birth int
140 
141 const (
142     // bornBefore: the process existed at the listing, with the slack to spare.
143     bornBefore birth = iota
144     // bornAround: too close to the listing instant to tell.
145     bornAround
146     // bornAfter: the process did not exist at the listing.
147     bornAfter
148 )
149 
150 // judgeBirth places a creation time (Unix ns) against the listing instant
151 // (Unix ns). The slack absorbs the granularity of the creation time and of the
152 // clock.
153 func judgeBirth(createdNs, listedAtNs int64, slack time.Duration) birth {
154     switch {
155     case createdNs <= listedAtNs-int64(slack):
156         return bornBefore
157     case createdNs > listedAtNs:
158         return bornAfter
159     default:
160         return bornAround
161     }
162 }
163 
164 // verdictAtSignal is the decision realOS.kill applies to what it read with the
165 // process held: nil means send. A failed read never sends, whatever the stamp.
166 func verdictAtSignal(pid int, want Identity, got uint64, readErr error) error {
167     if readErr != nil {
168         if errors.Is(readErr, os.ErrProcessDone) {
169             return fmt.Errorf("process %d: %w", pid, os.ErrProcessDone)
170         }
171         return &UnverifiableError{PID: pid, Cause: readErr}
172     }
173     if want.kind != identityKnown {
174         return &UnverifiableError{PID: pid}
175     }
176     if got != want.raw {
177         return &IdentityChangedError{PID: pid}
178     }
179     return nil
180 }
181 
182 // ConfirmIdentity gives the identity a stop of the row must be verified
183 // against. A known identity comes back as it is, with no system call; a
184 // deferred one (Windows, over the listing budget) is read now and anchored to
185 // the listing instant; an unknown one is refused. The errors are those of Kill:
186 // an OS refusal or a gone process stays readable through errors.Is, DevDesk's
187 // own refusals are an *UnverifiableError and an *IdentityChangedError.
188 func ConfirmIdentity(pid string, listed Identity) (Identity, error) {
189     n, ok := parsePID(pid)
190     if !ok || n <= 0 {
191         return Identity{}, fmt.Errorf("not a process id: %q", pid)
192     }
193     switch listed.kind {
194     case identityKnown:
195         return listed, nil
196     case identityDeferred:
197         return confirmDeferred(n, listed)
198     default:
199         return Identity{}, &UnverifiableError{PID: n}
200     }
201 }
202 
203 // confirmDeferred reads the stamp of a PID the listing did not read, and keeps
204 // it only if the process was born before the listing.
205 func confirmDeferred(n int, listed Identity) (Identity, error) {
206     raw, err := procOS.identity(n)
207     if err != nil {
208         if errors.Is(err, os.ErrPermission) || errors.Is(err, os.ErrProcessDone) {
209             return Identity{}, fmt.Errorf("reading the identity of process %d: %w", n, err)
210         }
211         return Identity{}, &UnverifiableError{PID: n, Cause: err}
212     }
213     switch judgeBirth(filetimeUnixNano(raw), int64(listed.raw), windowsBirthSlack) { //nolint:gosec // a listing instant fits in int64
214     case bornBefore:
215         return Identity{kind: identityKnown, raw: raw}, nil
216     case bornAfter:
217         return Identity{}, &IdentityChangedError{PID: n}
218     default:
219         return Identity{}, &UnverifiableError{PID: n}
220     }
221 }
