 12 // readIdentity reads the starttime of pid from /proc/<pid>/stat. A PID with no
 13 // process reads as os.ErrProcessDone.
 14 func readIdentity(pid int) (uint64, error) {
 15     path := "/proc/" + strconv.Itoa(pid) + "/stat"
 16     data, err := os.ReadFile(path)
 17     if err != nil {
 18         if errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ESRCH) {
 19             return 0, fmt.Errorf("reading %s: %w", path, os.ErrProcessDone)
 20         }
 21         return 0, err
 22     }
 23     return parseStartTicks(data)
 24 }
