 11 // readIdentity reads the start time of pid with sysctl kern.proc.pid. No such
 12 // process reads as os.ErrProcessDone: the kernel answers with no data, which
 13 // x/sys reports as EIO, and the record's own PID is checked as well.
 14 func readIdentity(pid int) (uint64, error) {
 15     kp, err := unix.SysctlKinfoProc("kern.proc.pid", pid)
 16     if err != nil {
 17         if errors.Is(err, unix.ESRCH) || errors.Is(err, unix.ENOENT) || errors.Is(err, unix.EIO) {
 18             return 0, fmt.Errorf("reading the process %d: %w", pid, os.ErrProcessDone)
 19         }
 20         return 0, err
 21     }
 22     if int(kp.Proc.P_pid) != pid {
 23         return 0, fmt.Errorf("reading the process %d: %w", pid, os.ErrProcessDone)
 24     }
 25     return timevalStamp(kp.Proc.P_starttime.Sec, kp.Proc.P_starttime.Usec), nil
 26 }
