 11 // creationOf reads the CreationTime of a process handle as one 64-bit FILETIME.
 12 func creationOf(h windows.Handle) (uint64, error) {
 13     var creation, exit, kernel, user windows.Filetime
 14     if err := windows.GetProcessTimes(h, &creation, &exit, &kernel, &user); err != nil {
 15         return 0, fmt.Errorf("reading the creation time: %w", err)
 16     }
 17     return uint64(creation.HighDateTime)<<32 | uint64(creation.LowDateTime), nil
 18 }
