 20 // readIdentity opens pid with the least rights that read its times. A refusal of
 21 // the system stays readable as os.ErrPermission, and an unknown PID reads as
 22 // os.ErrProcessDone.
 23 func readIdentity(pid int) (uint64, error) {
 24     h, err := windows.OpenProcess(windows.PROCESS_QUERY_LIMITED_INFORMATION, false, uint32(pid)) //nolint:gosec // a PID fits in a DWORD
 25     if err != nil {
 26         if errors.Is(err, windows.ERROR_INVALID_PARAMETER) {
 27             return 0, fmt.Errorf("opening the process: %w", os.ErrProcessDone)
 28         }
 29         return 0, fmt.Errorf("opening the process: %w", err)
 30     }
 31     defer windows.CloseHandle(h) //nolint:errcheck // nothing to do if closing fails
 32     return creationOf(h)
 33 }
