 35 // heldIdentity reads the creation time on the handle p holds, the one
 36 // os.FindProcess opened: the PID cannot be reassigned while it is open.
 37 func heldIdentity(p *os.Process, _ int) (uint64, error) {
 38     var raw uint64
 39     var readErr error
 40     if err := p.WithHandle(func(h uintptr) { raw, readErr = creationOf(windows.Handle(h)) }); err != nil {
 41         return 0, err
 42     }
 43     return raw, readErr
 44 }
 45 
 46 // isNoSuchProcess tells the failure of os.FindProcess for a PID nobody holds.
 47 func isNoSuchProcess(err error) bool { return errors.Is(err, windows.ERROR_INVALID_PARAMETER) }
