  9 // attachIdentities reads the identity of every distinct PID of the table once
 10 // and gives it to each row of that PID (DEVDESK-709, criterion 1). listedAt is
 11 // the instant taken before the socket snapshot.
 12 //
 13 // The PIDs are read in ascending order, so that when the Windows budget cuts the
 14 // reads it cuts the same PIDs from one refresh to the next. A PID that cannot be
 15 // read leaves its rows unknown.
 16 //
 17 // On Windows a creation time is a wall-clock time: a process born after the
 18 // listing (or too close to it to tell) is not the one that was listed, so its
 19 // row stays unknown. On Linux and macOS the stamp is not comparable with a clock
 20 // and is taken as read; the identity is read after the snapshot, so a PID that
 21 // changed hands in between would carry the newcomer's identity. That window is a
 22 // few milliseconds and needs a full turn of pid_max; it is accepted.
 23 func attachIdentities(sockets []Socket, listedAt time.Time) {
 24     pids := distinctPIDs(sockets)
 25     identities := make(map[string]Identity, len(pids))
 26     windows := goos == "windows"
 27     start := now()
 28     for _, pid := range pids {
 29         key := strconv.Itoa(pid)
 30         if windows && now().Sub(start) >= windowsIdentityBudget {
 31             identities[key] = deferredAt(listedAt)
 32             continue
 33         }
 34         identities[key] = readListedIdentity(pid, listedAt, windows)
 35     }
 36     for i := range sockets {
 37         sockets[i].Identity = identities[sockets[i].PID]
 38     }
 39 }
 40 
 41 // readListedIdentity reads one PID at listing time.
 42 func readListedIdentity(pid int, listedAt time.Time, windows bool) Identity {
 43     raw, err := procOS.identity(pid)
 44     if err != nil {
 45         return Identity{}
 46     }
 47     if windows && judgeBirth(filetimeUnixNano(raw), listedAt.UnixNano(), windowsBirthSlack) != bornBefore {
 48         return Identity{}
 49     }
 50     return Identity{kind: identityKnown, raw: raw}
 51 }
 52 
 53 // distinctPIDs is the sorted list of the PIDs the rows can be signalled by.
 54 func distinctPIDs(sockets []Socket) []int {
 55     var pids []int
 56     for _, s := range sockets {
 57         if n, ok := parsePID(s.PID); ok && n > 0 {
 58             pids = append(pids, n)
 59         }
 60     }
 61     slices.Sort(pids)
 62     return slices.Compact(pids)
 63 }

